# Set timezone to Europe/Berlin (CET in winter, CEST in summer)
os.environ["TZ"] = "CET-1CEST-2,M3.5.0/02:00:00,M10.5.0/03:00:00"
time.tzset()

berlin_tz = pytz.timezone("Europe/Berlin")
nyc_tz = pytz.timezone("America/New_York")
ktm_tz = pytz.timezone("Asia/Kathmandu")
utc_tz = pytz.timezone("UTC")

def make_mock_job(name=None):
    import unittest.mock as mock
    job = mock.Mock()
    job.__name__ = name or "job"
    return job

original_dt = datetime.datetime

def run_check(name, test_fn):
    """Helper to run a check and report results"""
    try:
        test_fn()
        print(f"  PASS: {name}")
        return True
    except AssertionError as e:
        print(f"  FAIL: {name}: {e}")
        return False
    except Exception as e:
        print(f"  ERROR: {name}: {type(e).__name__}: {e}")
        return False

passed = 0
failed = 0

