def test_hourly_kathmandu():
    """every().hour.at(":10", "Asia/Kathmandu") from 12:30 Berlin"""
    class MD(datetime.datetime):
        @classmethod
        def now(cls): return cls(2024, 1, 15, 12, 30, 0)
        @classmethod
        def today(cls): return cls(2024, 1, 15)
    datetime.datetime = MD

    schedule.clear()
    j = schedule.every().hour.at(":10", "Asia/Kathmandu").do(make_mock_job())

    # Berlin 12:30 = NPT 17:15. Next :10 in NPT = 18:10 NPT = 13:25 Berlin
    expected = datetime.datetime(2024, 1, 15, 13, 25, 0)
    assert j.next_run == expected, f"Expected {expected}, got {j.next_run}"

passed += run_check("hourly :10 NPT from 12:30 Berlin", test_hourly_kathmandu) and 1 or 0
failed += (1 if not test_hourly_kathmandu() else 0)  # re-run for failed count

datetime.datetime = original_dt

